$:set -euo pipefail
node <<'NODE'
const fs=require("node:fs");
let s=fs.readFileSync("workspaces/programs/scratchpad/SRS.md","utf8");
if(!s.includes("TP-SRS-001, v1.0.0")||s.includes("**PC-01:**"))throw Error("Unexpected SRS baseline");
s=s.replace("TP-SRS-001, v1.0.0","TP-SRS-001, v1.1.0");
const addition="## Reusable program-control comment lifecycle\n\n- **PC-01:** A program instance SHALL own its designated **control-comment ID** exclusively while active. This SHALL be distinct from permanent **scratchpad data-comment IDs**.\n- **PC-02:** Allocation SHALL bind a control-comment ID to a unique instance ID and monotonically increasing generation in durable program-session state.\n- **PC-03:** On completion or termination, the program SHALL release the control-comment binding and mark the comment available for another instance.\n- **PC-04:** A new instance SHALL be able to acquire a released comment ID with a new instance ID and incremented generation.\n- **PC-05:** Every session-scoped operation SHALL verify control-comment ID, instance ID and generation; stale instance commands SHALL be rejected.\n- **PC-06:** Release SHALL be idempotent for the same already-ended instance and SHALL NOT affect a newer owner.\n- **PC-07:** The durable lease state SHALL use an optimistic compare-and-swap update to prevent simultaneous allocation of a single control comment. Lease state SHALL be authoritative if UI rendering becomes stale.\n- **PC-08:** Completing or terminating a program SHALL NOT delete, truncate, recycle or rewrite its persistent scratchpad data comments.\n- **PC-09:** A program instance SHALL remain active across separate commands and workflow runs until completed, terminated or explicitly recovered. Finishing one command SHALL NOT automatically end the instance.\n- **PC-10:** Start, status and release responses SHALL identify the control-comment ID, instance ID, generation and current status.\n- **PC-11:** Abandoned sessions SHALL support a documented owner-authorized recovery operation, after which stale instance commands SHALL fail.\n\nThe lifecycle is: available → active → completed/terminated → available → active (new instance, new generation). The numeric control-comment ID is reusable; its ownership is not.\n\nThe program SHALL distinguish **control** comments used for menus and transient interaction from **data** comments carrying permanent scratchpad entries. The control-comment registry SHALL be persisted at workspaces/programs/sessions/state.json. The concrete release API SHALL use programInput operations complete and terminate with the current control_comment_id, instance_id, and generation. An explicit recover operation SHALL require the current generation and a reason.\n\n**Example:** Instance A acquires control comment 123 (generation 4), then completes. Instance B subsequently acquires comment 123 (generation 5). A subsequent request carrying A's instance ID or generation 4 SHALL be rejected as STALE_INSTANCE. A's scratchpad data-comment ID remains unchanged.\n\n";
s=s.replace("## Input contracts",addition+"## Input contracts");
fs.writeFileSync("workspaces/programs/scratchpad/SRS.md",s);
const file="workspaces/programs/scratchpad/SRS.agent.json";
const p=JSON.parse(fs.readFileSync(file,"utf8"));
if(p.version!=="1.0.0")throw Error("Unexpected projection baseline");
p.version="1.1.0";p.source.revision="1.1.0";
p.requirements.push(...[{"id":"PC-01","behavior":"Exclusive control-comment ownership during active instance; separate from permanent scratchpad data comments"},{"id":"PC-02","behavior":"Durable binding with unique instance ID and increasing generation"},{"id":"PC-03","behavior":"Complete/terminate release the control comment for reuse"},{"id":"PC-04","behavior":"Next instance can reuse numeric comment ID with new instance ID and generation"},{"id":"PC-05","behavior":"Reject stale commands by validating control comment, instance identity, and generation"},{"id":"PC-06","behavior":"Idempotent release cannot free a different owner's active lease"},{"id":"PC-07","behavior":"Optimistic CAS lease state is authoritative over transient UI"},{"id":"PC-08","behavior":"Ending program preserves all scratchpad data comments"},{"id":"PC-09","behavior":"Instance remains active between separate terminal commands until explicitly ended"},{"id":"PC-10","behavior":"Return control comment, instance, generation, status"},{"id":"PC-11","behavior":"Owner-authorized recovery of abandoned instances, rejecting stale commands"}]);
p.architecture.control_comment_lease={state_path:"workspaces/programs/sessions/state.json",issue_number:5,release_on:["complete","terminate","recover"],mode:"reusable",scope:"program-control comment only",lease_fields:["instance_id","generation","status"],data_comments:"independent persistent scratchpad data"};
p.data.program_control={control_comment_id:"positive integer",instance_id:"unique string",generation:"integer",status:"active | available"};
p.acceptance.push("complete and terminate release a reusable control comment","next instance can acquire same numeric comment ID with a different instance and generation","stale commands fail after reassignment","scratchpad data survive instance end","recovery safely releases abandoned sessions");
fs.writeFileSync(file,JSON.stringify(p,null,2)+"\n");
console.log(JSON.stringify({SRS:"1.1.0",projection:"1.1.0",requirements:p.requirements.length}));
NODE
for file in workspaces/programs/scratchpad/SRS.md workspaces/programs/scratchpad/SRS.agent.json; do
  current="$(gh api "repos/BestNameYet/Terminals/contents/$file" --jq .sha)"
  sha="$(gh api --method PUT "repos/BestNameYet/Terminals/contents/$file" -f sha="$current" -f message="Version scratchpad SRS 1.1.0: reusable control comment leases" -f content="$(base64 -w0 "$file")" --jq .commit.sha)"
  gh api "repos/BestNameYet/Terminals/contents/$file" --jq .content | tr -d '\n' | base64 -d > /tmp/srs-cmp
  cmp "$file" /tmp/srs-cmp
  printf 'VERIFIED %s %s\n' "$file" "$sha"
done
